/* @lc app=leetcode id=3830 lang=kotlin */ class Solution { fun longestAlternating(nums: IntArray): Int = nums.size.let { n -> IntArray(n).let { eu -> IntArray(n).let { ed -> IntArray(n).let { su -> IntArray(n).let { sd -> (0 until n).forEach { i -> eu.set(i, if (i > 0 && nums[i - 1] < nums[i]) ed[i - 1] + 1 else 1).also { ed[i] = if (i > 0 && nums[i - 1] > nums[i]) eu[i - 1] + 1 else 1 } }.let { (n - 1 downTo 0).forEach { i -> su.set(i, if (i < n - 1 && nums[i] < nums[i + 1]) sd[i + 1] + 1 else 1).also { sd[i] = if (i < n - 1 && nums[i] > nums[i + 1]) su[i + 1] + 1 else 1 } } }.let { maxOf((0 until n).maxOf { maxOf(eu[it], ed[it]) }, (1..n - 2).maxOfOrNull { j -> maxOf(if (nums[j - 1] > nums[j + 1]) eu[j - 1] + su[j + 1] else 0, if (nums[j - 1] < nums[j + 1]) ed[j - 1] + sd[j + 1] else 0) } ?: 0) } } } } } } }